mapper.select:
select id, file_name as fileName, description, size, stored_name as storedName, create_time as createTime
from file


        (create_time < #{cursorTime} or (create_time = #{cursorTime} and id < #{cursorId}))

    and status=#{status}
    and user_id=#{userId}

order by create_time desc, id desc
limit #{pageSize}

select id, file_name as fileName, description, size, stored_name as storedName, create_time as createTime
from file
where id=#{id}
and status=#{status}
and user_id=#{userId}

select id, file_name as fileName, description, size, stored_name as storedName, create_time as createTime
from file
where stored_name=#{storedName}
and status=#{status}
limit 1

mapper.update:
update file

    file_name=#{file.fileName},
    description=#{file.description},
    status=#{file.status},
    update_time=#{file.updateTime}

where id=#{file.id}
and user_id=#{userId}
